package main

import "testing"

// Every identity and history in this fixture is generated by the test helpers.
func TestSyntheticRecoveryActorContract(t *testing.T) {
	t.Run("accepted descendant selection", func(t *testing.T) {
		selection, actor, stored, _ := setupSingleActorReplication(t)
		result, err := runReplicationTransaction(selection)
		if err != nil || result.hasFailures() {
			t.Fatalf("normal synthetic import: %v %v", result.Outcomes, err)
		}
		assertRefValue(t, acceptedActorRef("origin", actor.Actor), stored.Commit)
		assertRefAbsent(t, actorRef(actor.Actor))
		next, err := nextEvent(actor, "issue.open")
		if err != nil || next.Sequence != stored.Event.Sequence+1 || next.Previous != stored.ID {
			t.Fatalf("accepted descendant was not selected: sequence=%d previous=%q want sequence=%d previous=%q err=%v", next.Sequence, next.Previous, stored.Event.Sequence+1, stored.ID, err)
		}
	})
	t.Run("append parenting", func(t *testing.T) {
		selection, actor, stored, _ := setupSingleActorReplication(t)
		result, err := runReplicationTransaction(selection)
		if err != nil || result.hasFailures() {
			t.Fatalf("normal synthetic import: %v %v", result.Outcomes, err)
		}
		e := newEvent(actor, "issue.open", stored.Event.Sequence+1, stored.ID)
		e.Title = "generated-key descendant"
		appended, err := appendEvent(e, actor)
		if err != nil {
			t.Fatalf("append against accepted descendant: %v", err)
		}
		parents := mustGitText(t, "show", "-s", "--format=%P", appended.Commit)
		if parents != stored.Commit {
			t.Fatalf("append parent=%q want accepted tip=%q", parents, stored.Commit)
		}
		assertRefValue(t, actorRef(actor.Actor), appended.Commit)
	})
	t.Run("incomparable chain refusal", func(t *testing.T) {
		selection, actor, _, _ := setupSingleActorReplication(t)
		e := newEvent(actor, "issue.open", 1, "")
		e.Title = "independent generated-key fork"
		local, err := appendEvent(e, actor)
		if err != nil {
			t.Fatal(err)
		}
		result, importErr := runReplicationTransaction(selection)
		if importErr == nil && !result.hasFailures() {
			if _, err := nextEvent(actor, "issue.open"); err == nil {
				t.Fatal("incomparable local and accepted chains allowed an append candidate")
			}
		}
		assertRefValue(t, actorRef(actor.Actor), local.Commit)
	})
}
